export interface HookVerdict {
  decision: "none" | "deny" | "ignored_allow" | "error";
  /** Set for `deny` and `error`. */
  denialReason?: Exclude<HookDenialReason, "HOOKS_CONFIG_INVALID">;
  reason?: string;
  ignored?: string[];
}

const DENY_DECISIONS = new Set(["block", "deny"]);
const ALLOW_DECISIONS = new Set(["approve", "allow"]);
const IGNORED_MEMBERS = ["updatedInput", "additionalContext", "suppressOutput", "systemMessage"];
const FAILURE_TEXT: Record<HookFailure, string> = {
  spawn: "the hook could not be started",
  timeout: "the hook did not finish in time and was stopped",
  stdout_oversize: `the hook wrote more than ${HOOK_STDOUT_LIMIT / 1024} KiB to standard output`,
  stderr_oversize: `the hook wrote more than ${HOOK_STDERR_LIMIT / 1024} KiB to standard error`,
  output_left_open: "the hook exited but something it started kept its output open, so its answer may be incomplete",
};

/**
 * What a finished hook run means. Pure. `deny` and `error` both refuse a tool call before it runs (`error` is the
 * fail-closed case); `none` and `ignored_allow` leave the call as the gates decided it. No result admits anything.
 */
export function reduceHookOutput(result: Pick<HookProcessResult, "exit" | "signal" | "stdout" | "stderr" | "failure" | "detail">): HookVerdict {
  const error = (reason: string, denialReason: HookVerdict["denialReason"] = "HOOK_FAILED"): HookVerdict => ({ decision: "error", denialReason, reason: hookLine(reason) });
  if (result.failure) return error(`${FAILURE_TEXT[result.failure]}${result.detail ? ` (${result.detail})` : ""}`);
  if (result.signal) return error(`the hook was ended by ${result.signal}`);
  if (result.exit === 2) return { decision: "deny", denialReason: "HOOK_DENIED", reason: hookLine(result.stderr) || "the hook exited with status 2" };
  if (result.exit !== 0) return error(`the hook exited with status ${result.exit}`);

  const text = result.stdout.trim();
  if (!text) return { decision: "none" };
  if (!text.startsWith("{")) return { decision: "none", reason: hookLine(text) };
  let answer: Record<string, unknown>;
  try {
    // The strict parser: with a repeated "decision" key, which one counts must not depend on the parser.
    answer = parseStrictJson(text, { maxDepth: 32 }) as Record<string, unknown>;
  } catch (problem) {
    return error(`the hook's output is not a valid JSON object: ${problem instanceof Error ? problem.message : String(problem)}`, "HOOK_OUTPUT_INVALID");
  }
  const specific = answer.hookSpecificOutput;
  if (specific !== undefined && (specific === null || typeof specific !== "object" || Array.isArray(specific))) return error("the hook's hookSpecificOutput is not an object", "HOOK_OUTPUT_INVALID");
  const nested = (specific ?? {}) as Record<string, unknown>;
  const text1 = (value: unknown) => (typeof value === "string" && value.trim() ? hookLine(value) : undefined);

  const ignored = [
    ...IGNORED_MEMBERS.filter((key) => key in answer),
    ...IGNORED_MEMBERS.filter((key) => key in nested).map((key) => `hookSpecificOutput.${key}`),
  ];
  const withIgnored = (verdict: HookVerdict): HookVerdict => (ignored.length ? { ...verdict, ignored } : verdict);
  const deny = (reason: string | undefined, fallback: string): HookVerdict => withIgnored({ decision: "deny", denialReason: "HOOK_DENIED", reason: reason ?? fallback });

  const { decision } = answer;
  const permission = nested.permissionDecision;
  // A denial anywhere in the answer wins over an allow anywhere else in it.
  if (typeof decision === "string" && DENY_DECISIONS.has(decision)) return deny(text1(answer.reason), `the hook answered ${decision}`);
  if (permission === "deny") return deny(text1(nested.permissionDecisionReason) ?? text1(answer.reason), "the hook answered deny");
  if (permission === "ask") return deny(text1(nested.permissionDecisionReason), "a hook asked for a human; this version treats ask as deny");
  if (answer.continue === false) return deny(text1(answer.stopReason) ?? text1(answer.reason), "the hook answered continue: false");
  // A decision this version does not know cannot be read as "no objection".
  if (decision !== undefined && !(typeof decision === "string" && ALLOW_DECISIONS.has(decision))) return withIgnored(error(`the hook's decision ${hookLine(JSON.stringify(decision), 80)} is not one of block, deny, approve, allow`, "HOOK_OUTPUT_INVALID"));
  if (permission !== undefined && permission !== "allow") return withIgnored(error(`the hook's permissionDecision ${hookLine(JSON.stringify(permission), 80)} is not one of allow, deny, ask`, "HOOK_OUTPUT_INVALID"));
  if (answer.continue !== undefined && answer.continue !== true) return withIgnored(error("the hook's continue is not true or false", "HOOK_OUTPUT_INVALID"));
  if (decision !== undefined || permission !== undefined) return withIgnored({ decision: "ignored_allow" });
  return withIgnored({ decision: "none" });
}

/** SHA-256 of a hook's standard output: the receipt names what was said without keeping it. */
export function hookOutputDigest(stdout: string): string {
  return createHash("sha256").update(stdout).digest("hex");
}
/**
 * The operator's approvals of repository-supplied extensions, keyed by the SHA-256 of their exact bytes
 * (`~/.config/nexus/extension_trust.json`). An approval names one content: changed bytes are a different content and
 * are not approved. A store that cannot be read safely or is malformed holds no approvals, so nothing it would have
 * approved runs; it never fails open.
 */
import * as os from "node:os";
import * as path from "node:path";
import { writePrivateFile } from "./durable_file.js";
import { decodeStrictUtf8, parseStrictJson, readHardenedFile } from "./strict_json.js";

export const EXTENSION_TRUST_VERSION = 1;
const STORE_LIMIT = 256 * 1024;

/** What an approval covers. `project-hooks`: a workspace's `.nexus/hooks.json`. */
export type ExtensionTrustKind = "project-hooks";
const KINDS: readonly string[] = ["project-hooks"] satisfies ExtensionTrustKind[];

export interface ExtensionTrustEntry {
  kind: ExtensionTrustKind;
  /** The workspace's real path. */
  scope: string;
  /** The approved item inside the scope (a path relative to the workspace). */
  key: string;
  /** SHA-256 of the approved bytes, 64 lowercase hexadecimal digits. */
  sha256: string;
  /** ISO 8601 time of the approval. */
  approvedAt: string;
  /** One line shown when approvals are listed. */
  summary: string;
}

/** The document in `extension_trust.json`. */
export interface ExtensionTrustStore {
  version: 1;
  entries: ExtensionTrustEntry[];
}

export type ExtensionTrustId = Pick<ExtensionTrustEntry, "kind" | "scope" | "key">;

/**
 * NEW: content that was never approved. MATCH: the approved content. MISMATCH: content that differs from the approved
 * one. REMOVED: approved, and there is none now. ABSENT: no content and no approval.
 */
export type ExtensionTrustStatus = "NEW" | "MATCH" | "MISMATCH" | "REMOVED" | "ABSENT";

export function extensionTrustStorePath(): string {
  return path.join(os.homedir(), ".config", "nexus", "extension_trust.json");
}

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === "object" && !Array.isArray(value);
const same = (a: ExtensionTrustId, b: ExtensionTrustId) => a.kind === b.kind && a.scope === b.scope && a.key === b.key;

function entryOf(raw: unknown): ExtensionTrustEntry | undefined {
  if (!isRecord(raw)) return undefined;
  const { kind, scope, key, sha256, approvedAt, summary } = raw;
  if (typeof kind !== "string" || !KINDS.includes(kind)) return undefined;
  if (typeof scope !== "string" || typeof key !== "string" || typeof approvedAt !== "string" || typeof summary !== "string") return undefined;
  if (typeof sha256 !== "string" || !/^[0-9a-f]{64}$/.test(sha256)) return undefined;
  return { kind: kind as ExtensionTrustKind, scope, key, sha256, approvedAt, summary };
}

/**
 * The approvals in the store. A missing store is empty. One that is not a private regular file of this user, or is
 * not a version 1 store, or has any malformed entry, is also empty and `problem` says why.
 */
export function readExtensionTrust(storePath = extensionTrustStorePath()): { entries: ExtensionTrustEntry[]; problem?: string } {
  try {
    const file = readHardenedFile(storePath, { maxBytes: STORE_LIMIT, forbiddenMode: 0o077 });
    if (!file) return { entries: [] };
    const parsed = parseStrictJson(decodeStrictUtf8(file.bytes));
    if (!isRecord(parsed) || parsed.version !== EXTENSION_TRUST_VERSION || !Array.isArray(parsed.entries)) return { entries: [], problem: "it is not a version 1 extension trust store" };
    const entries = parsed.entries.map(entryOf);
    // One bad entry means the file was not written by Nexus as it is now: none of it is believed.
    if (entries.some((entry) => entry === undefined)) return { entries: [], problem: "it has a malformed entry" };
    return { entries: entries as ExtensionTrustEntry[] };
  } catch (error) {
    return { entries: [], problem: error instanceof Error ? error.message : String(error) };
  }
}

/** How `currentSha256` (undefined: there is no content now) stands against the approval recorded for `id`. */
export function extensionTrustStatus(entries: readonly ExtensionTrustEntry[], id: ExtensionTrustId, currentSha256: string | undefined): ExtensionTrustStatus {
  const stored = entries.find((entry) => same(entry, id));
  if (currentSha256 === undefined) return stored ? "REMOVED" : "ABSENT";
  if (!stored) return "NEW";
  return stored.sha256 === currentSha256 ? "MATCH" : "MISMATCH";
}

function write(storePath: string, entries: ExtensionTrustEntry[]): void {
  const store: ExtensionTrustStore = { version: EXTENSION_TRUST_VERSION, entries };
  writePrivateFile(storePath, `${JSON.stringify(store, null, 2)}\n`, { durable: true });
}

/** Records the approval of exactly `entry.sha256`, replacing an earlier approval of the same item. A store that could not be read is replaced. */
export function approveExtension(entry: ExtensionTrustEntry, storePath = extensionTrustStorePath()): void {
  if (!entryOf(entry)) throw new Error("approveExtension: the entry is not a valid approval (sha256 must be 64 lowercase hexadecimal digits)");
  const kept = readExtensionTrust(storePath).entries.filter((other) => !same(other, entry));
  write(storePath, [...kept, entry]);
}

/** Removes the approval of `id`. Returns whether there was one. */
export function revokeExtension(id: ExtensionTrustId, storePath = extensionTrustStorePath()): boolean {
  const { entries } = readExtensionTrust(storePath);
  const kept = entries.filter((other) => !same(other, id));
  if (kept.length === entries.length) return false;
  write(storePath, kept);
  return true;
}

