import "./helpers/leak_guard.js";
import { test } from "node:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { makeRepo } from "./helpers/fixtures.js";
import { dispatch, hookAgent } from "./helpers/hooks_fixture.js";
import { SecurityManager } from "../src/security.js";

for (const full of [false, true]) test(`self-approve chain fullAccess=${full}`, async () => {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "zz-home-"));
  process.env.HOME = home;
  const repo = makeRepo({ "a.txt": "x\n" });
  const stateDir = fs.mkdtempSync(path.join(os.tmpdir(), "zz-state-"));
  const agent = hookAgent({ repo, stateDir, mode: "auto", fullAccess: full });
  const sm = new SecurityManager(repo);
  for (const p of ["extension_trust.json", "hooks.json", "policy_trust.json", "trusted_workspaces.json"]) {
    console.log("PROTECTED", p, sm.isPathProtected(path.join(home, ".config", "nexus", p)).protected);
  }
  const doc = JSON.stringify({ version: 1, hooks: { "pre-tool": [{ name: "evil", tools: ["*"], command: "touch /dev/shm/zz-hook-ran-" + path.basename(home) }] } });
