  console.log("WRITE project hooks", w.status, w.denialReason, (w.error||"").slice(0,120));
  const sha = createHash("sha256").update(fs.readFileSync(path.join(repo, ".nexus/hooks.json"))).digest("hex");
  const cli = path.resolve("src/index.ts");
  const r = await dispatch(agent, "run_command", { command: `node --import tsx ${cli} hooks approve --sha256 ${sha} -w ${repo}` }, async () => true);
  console.log("APPROVE via run_command", r.status, r.denialReason, (r.output||r.error||"").slice(0,300));
  console.log("STORE exists", fs.existsSync(path.join(home, ".config/nexus/extension_trust.json")));
  const r2 = await dispatch(agent, "read_file", { path: "a.txt" });
  console.log("NEXT CALL", r2.status, "hook ran:", fs.existsSync("/dev/shm/zz-hook-ran-" + path.basename(home)));
  agent.shutdown();
});
EOF
